INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39211, 'Leviticus 23:13', 'Leviticus', 23, 13, 'د هغې سره به تاسو د دوو کیلو ګرامو ښو اوړو د غلې دانې یوه نذرانه چې د زیتونو تېل ورسره ګډ وي وړاندې کړئ. دا یوه داسې نذرانه ده چې په اور باندې څښتن ته تیاریږي او بوی یې په هغه باندې ښه لګیږي. همدارنګه د هغې سره به تاسو د څښلو د نذرانې په توګه یو لیتر د شرابو نذرانه هم وړاندې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_13.mp3', '', 1761754199, 1761754199),
(39212, 'Leviticus 23:14', 'Leviticus', 23, 14, 'ترڅو پورې چې تاسو خدای ته دا نذرانه راوړې نه وي، نو نوې غلې دانې هېڅ مه خورئ. که هغه خامې وي، نینې شوې وي، یا ډوډۍ ورڅخه پخه شوې وي هغه دې ونه خوړل شي. په دې قانون باندې دې د تل دپاره ستاسو د ټولو نسلونو له خوا عمل وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_14.mp3', '', 1761754199, 1761754199),
(39213, 'Leviticus 23:15', 'Leviticus', 23, 15, 'د سبت د ورځې په سبا چې تاسو په کې څښتن ته د وړاندې کولو دپاره خپلې ګېډۍ راوړئ، پوره اووه هفتې وشمېرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_15.mp3', '', 1761754199, 1761754199),
(39214, 'Leviticus 23:16', 'Leviticus', 23, 16, 'په پنځوسمه ورځ، یعنې هغه ورځ چې د اووم سبت څخه وروسته وي، د نوي حاصل څخه څښتن ته د غلې دانې بله نذرانه وړاندې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_16.mp3', '', 1761754199, 1761754199),
(39215, 'Leviticus 23:17', 'Leviticus', 23, 17, 'هره کورنۍ دې دوه ډوډۍ راوړي چې ماته د وقف کولو دپاره پورته ونیول شي. هره یوه دې د دوو کیلو ګرامو ښو اوړو څخه پخه شوې وي او خمیره هم په کې وي. دا به څښتن ته د لومړنیو رېبل شویو غلو دانو د نذرانې په توګه وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_17.mp3', '', 1761754199, 1761754199),
(39216, 'Leviticus 23:18', 'Leviticus', 23, 18, 'قوم دې د ډوډۍ سره اووه یو کلن وري، یو غویی او دوه پسونه وړاندې کړي، د دغو څخه دې په یو کې هم کوم عیب نه وي. دا به د غلې دانې او د څښلو د نذرانې سره څښتن ته یوه سوځېدونکې نذرانه وي، یوه داسې نذرانه چې بوی یې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_18.mp3', '', 1761754199, 1761754199),
(39217, 'Leviticus 23:19', 'Leviticus', 23, 19, 'بیا د ګناه د نذرانې دپاره یو سېرلی او د سلامتۍ د نذرانې دپاره دوه یو کلن وري قرباني کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_19.mp3', '', 1761754199, 1761754199),
(39218, 'Leviticus 23:20', 'Leviticus', 23, 20, 'کاهن دې هغه ډوډۍ چې د لومړنیو رېبل شویو غلو دانو نښه ده، د دوه وریو سره څښتن ته د وقف کېدلو په خاطر پورته ونیسي. دا څښتن ته یوه سپېڅلې نذرانه ده چې باید کاهنانو ته ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_20.mp3', '', 1761754199, 1761754199),
(39219, 'Leviticus 23:21', 'Leviticus', 23, 21, 'تاسو باید په هماغه ورځ د عبادت دپاره سره راټول شئ او هېڅ ورځنی کار ونه کړئ. هر چېرته چې ستاسو اولاده اوسیږي، دا مقررات دې تل ترتله مراعت کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_21.mp3', '', 1761754199, 1761754199),
(39220, 'Leviticus 23:22', 'Leviticus', 23, 22, 'کله چې تاسو د خپلو ځمکو حاصلات لو کوئ، نو هغه د پټیو تر غاړو پورې مه لو کوئ او هغه وږي چې د لو څخه پاتې شوي وي، هغه مه راټولوئ. هغه غریبانو او پردیو خلکو ته پرېږدئ. زه ستاسو څښتن خدای یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_22.mp3', '', 1761754199, 1761754199),
(39221, 'Leviticus 23:23', 'Leviticus', 23, 23, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_23.mp3', '', 1761754199, 1761754199),
(39222, 'Leviticus 23:24', 'Leviticus', 23, 24, '«د اسراییلو قوم ته ووایه چې د هر کال د اوومې میاشتې لومړۍ ورځ د ارام کولو ځانګړې ورځ ده او د اسراییلو ټول خلک دې د سرني د اواز په اورېدلو سره د عبادت دپاره سره راټول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_24.mp3', '', 1761754199, 1761754199),
(39223, 'Leviticus 23:25', 'Leviticus', 23, 25, 'په هماغه ورځ خپل عادي کار مه کوئ، خو څښتن ته یوه داسې نذرانه وړاندې کړئ چې په اور باندې تیاریږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_25.mp3', '', 1761754199, 1761754199),
(39224, 'Leviticus 23:26', 'Leviticus', 23, 26, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_26.mp3', '', 1761754199, 1761754199),
(39225, 'Leviticus 23:27', 'Leviticus', 23, 27, '«هر کال د اوومې میاشتې لسمه ورځ د کفارې ورځ ده. په هغه ورځ د عبادت دپاره سره راټول شئ او روژه ونیسئ. یوه داسې نذرانه وړاندې کړئ چې څښتن ته په اور باندې تیاریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_27.mp3', '', 1761754199, 1761754199),
(39226, 'Leviticus 23:28', 'Leviticus', 23, 28, 'په هغه ورځ هېڅ کار مه کوئ، ځکه چې دا د کفارې ورځ ده چې ستاسو دپاره ستاسو د څښتن خدای په حضور کې کفاره ادا کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_28.mp3', '', 1761754199, 1761754199),
(39227, 'Leviticus 23:29', 'Leviticus', 23, 29, 'هرڅوک چې په هغه ورځ روژه ونه نیسي باید د خدای د قوم څخه وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_29.mp3', '', 1761754199, 1761754199),
(39228, 'Leviticus 23:30', 'Leviticus', 23, 30, 'که چېرې څوک په هغه ورځ کوم کار وکړي، زه به په خپله هغه ووژنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_30.mp3', '', 1761754199, 1761754199),
(39229, 'Leviticus 23:31', 'Leviticus', 23, 31, 'دا قانون ستاسو په ټوله اولاده باندې هر چېرته چې اوسیږي، عملي کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_31.mp3', '', 1761754199, 1761754199),
(39230, 'Leviticus 23:32', 'Leviticus', 23, 32, 'د هغې میاشتې په نهمه ورځ د لمرپرېواته څخه نیولې د میاشتې د لسمې ورځې تر لمرپرېواته پورې دا ورځ د ارام کولو د یوې ځانګړې ورځې په توګه ولمانځئ او په دې دوران کې باید تاسو روژه ونیسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_32.mp3', '', 1761754199, 1761754199),
(39231, 'Leviticus 23:33', 'Leviticus', 23, 33, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_33.mp3', '', 1761754199, 1761754199),
(39232, 'Leviticus 23:34', 'Leviticus', 23, 34, '«اسراییلیانو ته ووایه چې د اوومې میاشتې په پنځلسمه ورځ څښتن ته د درناوۍ دپاره د جونګړو اختر پیل کیږي. هغه اووه ورځې دوام کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_34.mp3', '', 1761754199, 1761754199),
(39233, 'Leviticus 23:35', 'Leviticus', 23, 35, 'په دغو ورځو کې لومړۍ ورځ د عبادت دپاره سره راټول شئ او خپل ورځنی کار مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_35.mp3', '', 1761754199, 1761754199),
(39234, 'Leviticus 23:36', 'Leviticus', 23, 36, 'اووه ورځې څښتن ته داسې نذرانې وړاندې کړئ چې په اور باندې تیاریږي او په اتمه ورځ بیا د عبادت دپاره سره راټول شئ او د پخوا په شان نذرانه وړاندې کړئ. دا د عبادت ورځ ده او تاسو به خپل عادي کار نه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_36.mp3', '', 1761754199, 1761754199),
(39235, 'Leviticus 23:37', 'Leviticus', 23, 37, 'دا هغه اخترونه دي چې د څښتن له خوا ټاکل شوي دي. هغه داسې ولمانځئ چې سره راټول شئ او هغه ډول ډول نذرانې چې په اور باندې څښتن ته تیاریږي یعنې سوځېدونکې نذرانې، د غلو دانو نذرانې، قربانۍ او د څښلو نذرانې، دا هره یوه دې په خپله مناسبه ورځ هغه ته وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_37.mp3', '', 1761754199, 1761754199),
(39236, 'Leviticus 23:38', 'Leviticus', 23, 38, 'دا اخترونه د سبت د ورځو څخه بېل دي او دا نذرانې د عادي سوغاتونو څخه بېلې دي، یعنې ستاسو د هغو نذرانو څخه چې د نذرونو دپاره دي او د هغو د خپلې خوښې نذرانو څخه چې څښتن ته یې ورکوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_38.mp3', '', 1761754199, 1761754199),
(39237, 'Leviticus 23:39', 'Leviticus', 23, 39, 'نو کله چې تاسو خپل پټي ورېبل، اووه ورځې دا اختر چې د اوومې میاشتې په پنځلسمه ورځ پیل کیږي، ولمانځئ. لومړۍ ورځ به د ارام کولو ورځ وي او اتمه ورځ به هم د ارام کولو ورځ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_39.mp3', '', 1761754199, 1761754199),
(39238, 'Leviticus 23:40', 'Leviticus', 23, 40, 'په لومړۍ ورځ تاسو د خپلو ونو څخه ډېره ښه مېوه، د خرما د ونې څانګې، پاڼې لرونکې څانګې او د سیند د غاړو څخه ولې واخلئ او اووه ورځې د خپل څښتن خدای په حضور کې خوشحالي وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_40.mp3', '', 1761754199, 1761754199),
(39239, 'Leviticus 23:41', 'Leviticus', 23, 41, 'دا هر کال اووه ورځې څښتن ته د درناوي دپاره د یو اختر په توګه ولمانځئ. ستاسو راتلونکې اولاده دې تل ترتله د دې قانون څخه پیروي وکړي. هغه په اوومه میاشت ولمانځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_41.mp3', '', 1761754199, 1761754199),
(39240, 'Leviticus 23:42', 'Leviticus', 23, 42, 'د اسراییلو ټول خلک باید اووه ورځې په جونګړو کې واوسیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_42.mp3', '', 1761754199, 1761754199),
(39241, 'Leviticus 23:43', 'Leviticus', 23, 43, 'ترڅو ستاسو اولاده په دې پوه شي کله چې ما د اسراییلو قوم د مصر څخه راوویست، هغوی مې دې ته مجبور کړل چې په ساده جونګړو کې واوسیږي. زه ستاسو څښتن خدای یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_43.mp3', '', 1761754199, 1761754199),
(39242, 'Leviticus 23:44', 'Leviticus', 23, 44, 'نو په دې ډول موسی د اسراییلو خلکو ته لارښوونه وکړه چې د څښتن اخترونه ولمانځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_44.mp3', '', 1761754199, 1761754199),
(39243, 'Psalms 143:1', 'Psalms', 143, 1, 'ای څښتنه، زما دعا واوره زما زاریو ته ته غوږ ونیسه خپلې وفادارۍ او عدالت سره قبوله کړه دعا زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_1.mp3', '', 1761754199, 1761754199),
(39244, 'Psalms 143:2', 'Psalms', 143, 2, 'خپل خدمتګار دې محاکمه نه کړې ته څوک بې‌ګناه نشته دی ستا نظر کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_2.mp3', '', 1761754199, 1761754199),
(39245, 'Psalms 143:3', 'Psalms', 143, 3, 'دښمنان په ما پسې دي او زه یې ځپلی یمه زه یې اچولی یم تیاره ځای کې د هغو خلکو په شان چې دي مړه شوي ډېر پخوا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_3.mp3', '', 1761754199, 1761754199),
(39246, 'Psalms 143:4', 'Psalms', 143, 4, 'نو کمزوری شوی زما روح دی ډېر وېرېدلی او نا‌امیده یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_4.mp3', '', 1761754199, 1761754199),
(39247, 'Psalms 143:5', 'Psalms', 143, 5, 'رایادومه تېر وختونه زه کوم کارونه چې تا کړي دي د هغو ټولو په هکله کومه فکر زه ستا ټول کارونه راولم ذهن ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_5.mp3', '', 1761754199, 1761754199),
(39248, 'Psalms 143:6', 'Psalms', 143, 6, 'پورته کومه خپل لاسونه په دعا کې تاته د وچې ځمکې په شان تږی زما ځان دی تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_6.mp3', '', 1761754199, 1761754199),
(39249, 'Psalms 143:7', 'Psalms', 143, 7, 'زر مې قبوله کړه دعا څښتنه ټول امیدونه مې ورکړي دي له لاسه ته دې خپل مخ له ما نه مه اړوه که نه نو زه به د هغو په شان شم چې وي روان قبر ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_7.mp3', '', 1761754199, 1761754199),
(39250, 'Psalms 143:8', 'Psalms', 143, 8, 'هر سهار راته رایاده کړه ته خپله تلپاتې مینه ځکه چې تا باندې باور لرمه ستا درګاه ته زه دعا کومه راته وښایه ته لاره چې پرې لاړ شمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_8.mp3', '', 1761754199, 1761754199),
(39251, 'Psalms 143:9', 'Psalms', 143, 9, 'د دښمنانو نه مې خلاص کړه ته ځکه چې تاته مې راوړې ده پناه څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_9.mp3', '', 1761754199, 1761754199),
(39252, 'Psalms 143:10', 'Psalms', 143, 10, 'ته زما خدای یې، ماته وښایه ته خپله رضا چې یې پوره کړمه زه ستا نېک روح دې ماته وښایي سمه لاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_10.mp3', '', 1761754199, 1761754199),
(39253, 'Psalms 143:11', 'Psalms', 143, 11, 'د خپل نوم په خاطر دې ای څښتنه زما ژوند وساته خپل عدالت په خاطر خلاص کړه تکلیفونو نه ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_11.mp3', '', 1761754199, 1761754199),
(39254, 'Psalms 143:12', 'Psalms', 143, 12, 'د خپلې تلپاتې مینې په خاطر مړه دښمنان کړه زما تباه کړه هغه خلک چې کوي ظلم په ما ځکه چې زه ستا خدمتګار یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms143_verse_12.mp3', '', 1761754199, 1761754199),
(39255, 'Numbers 17:1', 'Numbers', 17, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_1.mp3', '', 1761754199, 1761754199),
(39256, 'Numbers 17:2', 'Numbers', 17, 2, '«د اسراییلو خلکو ته ووایه چې دولس امساګانې درکړي یعنې د هرې قبیلې د مشر څخه یوه یوه دانه. د هر سړي نوم د هغه په امسا باندې ولیکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_2.mp3', '', 1761754199, 1761754199),
(39257, 'Numbers 17:3', 'Numbers', 17, 3, 'او بیا د هارون نوم د لاویانو په امسا باندې ولیکه. د هر قبیلوي مشر دپاره دې یوه یوه امسا وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_3.mp3', '', 1761754199, 1761754199),
(39258, 'Numbers 17:4', 'Numbers', 17, 4, 'دا امساګانې په سپېڅلې خېمه کې د لوظ د صندوق په مخکې چېرته چې زه تاسو سره ملاقات کوم، کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_4.mp3', '', 1761754199, 1761754199),
(39259, 'Numbers 17:5', 'Numbers', 17, 5, 'بیا به د هغه کس امسا غوټۍ ونیسي چې زه یې غوره کوم. په دې ډول به ستاسو په خلاف د دغو اسراییلیانو دوامداره شکایتونو ته د پای ټکی کېږدم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_5.mp3', '', 1761754199, 1761754199),
(39260, 'Numbers 17:6', 'Numbers', 17, 6, 'موسی د اسراییلیانو سره خبرې وکړې او د هغوی هر یو مشر موسی ته امسا ورکړه، یعنې د هرې قبیلې څخه یوه یوه دانه چې ټولې دولس وې او د هارون امسا هم په کې شامله وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_6.mp3', '', 1761754199, 1761754199),
(39261, 'Numbers 17:7', 'Numbers', 17, 7, 'بیا موسی ټولې امساګانې په خېمه کې د څښتن د لوظ د صندوق مخې ته کېښودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_7.mp3', '', 1761754199, 1761754199),
(39262, 'Numbers 17:8', 'Numbers', 17, 8, 'په سبا ورځ کله چې موسی خېمې ته ورننوت، هغه ولیدل چې د هارون امسا چې د لاوي د قبیلې استازیتوب یې کوله تېغ وهلی. هغې غوټۍ کړې وې، ګلان یې نیولي وو او بادام یې کړي وو!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_8.mp3', '', 1761754199, 1761754199),
(39263, 'Numbers 17:9', 'Numbers', 17, 9, 'موسی هغه دولس امساګانې له خېمې څخه راوویستلې او خلکو ته یې ورښکاره کړې. هر مشر خپله امسا راپیدا کړه او هغه یې واخیستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_9.mp3', '', 1761754199, 1761754199),
(39264, 'Numbers 17:10', 'Numbers', 17, 10, 'خو څښتن موسی ته وویل: «د هارون امسا بېرته د لوظ صندوق ته مخامخ کېږده! پرېږده چې هغه هلته پاتې وي او د هغه چا دپاره چې د سرکښۍ کولو په اړه فکر کوي د خبرداري په توګه وي. که چېرې دا خلک زما په هکله شکایت بس نه کړي، نو زه به یې له منځه یوسم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_10.mp3', '', 1761754199, 1761754199),
(39265, 'Numbers 17:11', 'Numbers', 17, 11, 'لکه څنګه چې څښتن حکم کړی ؤ، موسی هماغسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_11.mp3', '', 1761754199, 1761754199),
(39266, 'Numbers 17:12', 'Numbers', 17, 12, 'اسراییلیانو موسی ته فریاد وکړ او ویې ویل: «مونږ مړه کېږو! زمونږ دپاره کومه هیله نشته، مونږ ټول له منځه ځو!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_12.mp3', '', 1761754199, 1761754199),
(39267, 'Numbers 17:13', 'Numbers', 17, 13, 'حتی هرڅوک چې سپېڅلې خېمې ته ورنژدې شي، هغه به مړ شي. نو مونږ ټول به مړه شو!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers17_verse_13.mp3', '', 1761754199, 1761754199),
(39268, 'Numbers 20:1', 'Numbers', 20, 1, 'د اسراییلو ټول قوم د کال د اولې میاشتې په دوران کې د صین دښتې ته راورسېد او په قادش کې یې خېمې ودرولې. دا هغه ځای ؤ چې مریم په کې مړه شوه او ښخه کړای شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_1.mp3', '', 1761754199, 1761754199),
(39269, 'Numbers 20:2', 'Numbers', 20, 2, 'په کوم ځای کې چې هغوی خېمې ودرولې وې هلته اوبه نه وې، نو خلک د موسی او هارون په ضد راټول شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_2.mp3', '', 1761754199, 1761754199),
(39270, 'Numbers 20:3', 'Numbers', 20, 3, 'هغوی موسی ته شکایت وکړ او ویې ویل: «دا به ښه وای چې مونږ د نورو اسراییلیانو سره د څښتن په حضور کې مړه شوي وای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_3.mp3', '', 1761754199, 1761754199),
(39271, 'Numbers 20:4', 'Numbers', 20, 4, 'تا ولې مونږ دې دښتې ته راوستلو؟ یوازې د دې دپاره چې د خپلو حیواناتو سره دلته مړه شو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_4.mp3', '', 1761754199, 1761754199),
(39272, 'Numbers 20:5', 'Numbers', 20, 5, 'ولې دې مونږ د مصر څخه دې خوار ځای ته چې هېڅ شی په کې نه شنه کیږي راوستلو؟ دلته نه غله شته، نه انځران، نه انګور او نه انار. حتی د څښلو اوبه هم دلته نشته!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_5.mp3', '', 1761754199, 1761754199),
(39273, 'Numbers 20:6', 'Numbers', 20, 6, 'موسی او هارون د خلکو څخه لېرې لاړل او د سپېڅلې خېمې په دروازه کې ودرېدل. هغوی په سجده شول او د څښتن جلال ورته ښکاره شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_6.mp3', '', 1761754199, 1761754199),
(39274, 'Numbers 20:7', 'Numbers', 20, 7, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_7.mp3', '', 1761754199, 1761754199),
(39275, 'Numbers 20:8', 'Numbers', 20, 8, '«هغه امسا چې د لوظ د صندوق په مخکې پرته ده راواخله او بیا ته او هارون ټول قوم راټول کړئ. د هغو ټولو په مخکې هغه ګټ ته ووایئ چې اوبه ورڅخه جاري شي. په دې ډول به ته د ګټ څخه خلکو او د هغو حیواناتو ته د څښلو دپاره اوبه راوباسې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_8.mp3', '', 1761754199, 1761754199),
(39276, 'Numbers 20:9', 'Numbers', 20, 9, 'نو موسی لاړ او څنګه چې څښتن ورته حکم کړی ؤ، امسا یې راواخیستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_9.mp3', '', 1761754199, 1761754199),
(39277, 'Numbers 20:10', 'Numbers', 20, 10, 'هغه او هارون ټول قوم د ګټ مخې ته راټول کړ او موسی ورته وویل: «ای سرکښو خلکو، واورئ! ایا مونږ باید تاسو ته د دې ګټ څخه اوبه راوباسو؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_10.mp3', '', 1761754199, 1761754199),
(39278, 'Numbers 20:11', 'Numbers', 20, 11, 'بیا موسی امسا پورته کړه او ګټ یې دوه ځلې ورباندې وواهه او د هغه څخه د اوبو یوه لویه ویاله جاري شوه او ټولو خلکو او حیواناتو هغه وڅښلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_11.mp3', '', 1761754199, 1761754199),
(39279, 'Numbers 20:12', 'Numbers', 20, 12, 'خو څښتن موسی او هارون ورټل او ورته ویې ویل: «څرنګه چې تاسو په ما باندې اعتماد ونه کړ چې د اسراییلو د خلکو په مخکې زما د پاک قدرت درناوی وکړئ، نو تاسو به ونه شئ کولای چې هغوی هغې خاورې ته بوځئ چې د هغې د ورکولو وعده مې د هغوی سره کړې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_12.mp3', '', 1761754199, 1761754199),
(39280, 'Numbers 20:13', 'Numbers', 20, 13, 'دا پېښه په مریبه کې وشوه، یعنې هغه ځای چې اسراییلیانو په کې د څښتن په خلاف شکایت وکړ او څښتن هغوی ته خپل سپېڅلتوب وروښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_13.mp3', '', 1761754199, 1761754199),
(39281, 'Numbers 20:14', 'Numbers', 20, 14, 'موسی د قادش څخه د ادوم پاچا ته استازي ولېږل چې دا پیغام ورته ورسوي: «مونږ اسراییلیان ستاسو خپل خپلوان یو او تاسو خبر یئ چې په مونږ باندې څومره سختۍ تېرې شوې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_14.mp3', '', 1761754199, 1761754199),
(39282, 'Numbers 20:15', 'Numbers', 20, 15, 'څنګه زمونږ نیکونه مصر ته لاړل او مونږ د ډېرو کلونو دپاره هلته اوسېدلو. مصریانو زمونږ د نیکونو او زمونږ سره بد چلند وکړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_15.mp3', '', 1761754199, 1761754199),
(39283, 'Numbers 20:16', 'Numbers', 20, 16, 'او مونږ څښتن ته د مرستې دپاره فریاد وکړ. هغه زمونږ فریاد واورېد او فرښته یې راولېږله او مونږ یې د مصر څخه راوویستلو. اوس مونږ په قادش کې یو چې دا یو ښار دی چې ستاسو د سیمې سره سرحد لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_16.mp3', '', 1761754199, 1761754199),
(39284, 'Numbers 20:17', 'Numbers', 20, 17, 'مهرباني وکړئ مونږ ته اجازه راکړئ چې ستاسو د هېواد څخه تېر شو. مونږ به خپله لاره نه پرېنږدو او ستاسو پټیو او د انګورو باغونو ته به نه ورننوځو او ستاسو د څاه ګانو څخه به هېڅ اوبه ونه څښو. مونږ به په لویه لاره باندې ځو، ترڅو ستاسو د سیمې څخه ووځو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_17.mp3', '', 1761754199, 1761754199),
(39285, 'Numbers 20:18', 'Numbers', 20, 18, 'خو ادومیانو په ځواب کې وویل: «نه، مونږ به تاسو پرېنږدو چې زمونږ د هېواد په لاره باندې لاړ شئ! او که چېرې تاسو د دې کار هڅه وکړئ، مونږ به ووځو او حمله به درباندې وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_18.mp3', '', 1761754199, 1761754199),
(39286, 'Numbers 20:19', 'Numbers', 20, 19, 'د اسراییلو خلکو وویل: «مونږ به په لویه لاره باندې ځو او که مونږ یا زمونږ حیواناتو ستاسو اوبه وڅښلې، مونږ به یې بیه درکړو. مونږ یوازې غواړو چې تېر شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_19.mp3', '', 1761754199, 1761754199),
(39287, 'Numbers 20:20', 'Numbers', 20, 20, 'خو ادومیانو بیا وویل: «مونږ یې نه منو!» او هغوی د یو قوي لښکر سره ووتل چې د اسراییلو په خلکو باندې حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_20.mp3', '', 1761754199, 1761754199),
(39288, 'Numbers 20:21', 'Numbers', 20, 21, 'څرنګه چې ادومیانو اسراییلیانو ته اجازه ورنه کړه چې د هغوی د سیمې له لارې تېر شي، نو اسراییلیان بېرته ستانه شول او په بله لاره باندې لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_21.mp3', '', 1761754199, 1761754199),
(39289, 'Numbers 20:22', 'Numbers', 20, 22, 'د اسراییلو ټول قوم د قادش څخه لاړ او د هور غره ته ورسېدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_22.mp3', '', 1761754199, 1761754199),
(39290, 'Numbers 20:23', 'Numbers', 20, 23, 'یعنې د ادوم سرحد ته. په هغه ځای کې څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_23.mp3', '', 1761754199, 1761754199),
(39291, 'Numbers 20:24', 'Numbers', 20, 24, '«هارون به هغې خاورې ته داخل نه شي چې د هغې د ورکولو وعده مې د اسراییلیانو سره کړې ده. هغه به مړ شي او د خپلو نیکونو سره به یوځای شي، ځکه چې تاسو دواړو په مریبه کې زما د حکم څخه سرغړونه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_24.mp3', '', 1761754199, 1761754199),
(39292, 'Numbers 20:25', 'Numbers', 20, 25, 'هارون او د هغه زوی العازار درسره واخله او د هور د غره سرته یې وخېژوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_25.mp3', '', 1761754199, 1761754199),
(39293, 'Numbers 20:26', 'Numbers', 20, 26, 'او په هغه ځای کې د هارون څخه د کاهنتوب کالي وباسه او العازار ته یې ورواغونده. هارون به هلته مړ شي او د خپلو نیکونو سره به یوځای شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_26.mp3', '', 1761754199, 1761754199),
(39294, 'Numbers 20:27', 'Numbers', 20, 27, 'څه چې څښتن حکم کړی ؤ موسی هماغسې وکړل. ټول قوم ورته کتل چې هغوی د هور د غره سرته وختل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_27.mp3', '', 1761754199, 1761754199),
(39295, 'Numbers 20:28', 'Numbers', 20, 28, 'موسی د هارون څخه د کاهنتوب کالي لېرې کړل او د هغه زوی العازار ته یې ورواغوستل. هارون هلته د هور د غره په سر باندې مړ شو او موسی او العازار بېرته راښکته شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_28.mp3', '', 1761754199, 1761754199),
(39296, 'Numbers 20:29', 'Numbers', 20, 29, 'کله چې د اسراییلو ټول قوم خبر شو چې هارون مړ شوی دی، نو هغوی دېرش ورځې د هغه په مرګ باندې غم او ژړا وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers20_verse_29.mp3', '', 1761754199, 1761754199),
(39297, 'Hosea 4:1', 'Hosea', 4, 1, 'ای د اسراییلو خلکو، د څښتن خبرو ته غوږ ونیسئ. څښتن د دې وطن په اوسېدونکو باندې تور لګوي، ځکه چې په دې وطن کې نه وفاداري شته، نه مینه او دا خلک خدای نه پېژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_1.mp3', '', 1761754199, 1761754199),
(39298, 'Hosea 4:2', 'Hosea', 4, 2, 'هغوی په نورو باندې لعنت وایي، دروغ وایي، قتل کوي، غلا کوي او زنا کوي. جرمونه زیاتیږي او د یو قتل پسې بل قتل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_2.mp3', '', 1761754199, 1761754199),
(39299, 'Hosea 4:3', 'Hosea', 4, 3, 'نو له همدې امله به دا ځمکه وچه شي او هر ژوندی موجود، ټول ځنګلي حیوانات، مرغان او حتی ماهیان به هم مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_3.mp3', '', 1761754199, 1761754199),
(39300, 'Hosea 4:4', 'Hosea', 4, 4, 'څښتن وایي: «هېڅوک دې په خلکو باندې تور نه لګوي او نه دې هغوی ملامتوي. زما ګیله ستاسو کاهنانو څخه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_4.mp3', '', 1761754199, 1761754199),
(39301, 'Hosea 4:5', 'Hosea', 4, 5, 'تاسو او پیغمبران شپه او ورځ خطاګانې کوئ. زه به ستاسو مور یعنې اسراییل تباه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_5.mp3', '', 1761754199, 1761754199),
(39302, 'Hosea 4:6', 'Hosea', 4, 6, 'زما قوم تباه دی، ځکه چې هغوی ما نه پېژني. تاسو کاهنانو زما د پېژندلو نه انکار کړی دی، نو زه به تاسو د خپلو کاهنانو په توګه ونه پېژنم. څرنګه چې تاسو زما قوانین هېر کړي دي، نو زه به هم ستاسو اولادونه هېر کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_6.mp3', '', 1761754199, 1761754199),
(39303, 'Hosea 4:7', 'Hosea', 4, 7, 'هرڅومره چې تاسو کاهنان زیاتیږئ په هماغه اندازه زما په وړاندې ستاسو ګناهونه زیاتیږي، نو زه به ستاسو عزت په بې‌عزتۍ باندې بدل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_7.mp3', '', 1761754199, 1761754199),
(39304, 'Hosea 4:8', 'Hosea', 4, 8, 'کله چې خلک خپلې سوځېدونکې نذرانې راوړي، نو تاسو کاهنان ورباندې ځانونه مړوئ. کله چې خلک ګناه کوي، نو تاسو کاهنان خوشحالېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_8.mp3', '', 1761754199, 1761754199),
(39305, 'Hosea 4:9', 'Hosea', 4, 9, 'کوم کارونه چې تاسو کاهنان یې کوئ، نو خلک یې هم کوي او تاسو دواړو ته به د هغوی د بدو عملونو سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_9.mp3', '', 1761754199, 1761754199),
(39306, 'Hosea 4:10', 'Hosea', 4, 10, 'تاسو به د قربانیو نه خپله برخه خورئ، خو بیا به هم وږي یئ. تاسو به زناکاري کوئ خو اولادونه به مو نه پیدا کیږي، ځکه چې زه مو پریښی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_10.mp3', '', 1761754199, 1761754199),
(39307, 'Hosea 4:11', 'Hosea', 4, 11, 'د نورو خدایانو پیروي کول او شراب څښل که نوي یا زاړه وي، زما د خلکو عقل له منځه وړي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_11.mp3', '', 1761754199, 1761754199),
(39308, 'Hosea 4:12', 'Hosea', 4, 12, 'زما خلک د لرګي د بتانو سره مشوره کوي! هغوی فکر کوي چې هغه د لرګي امسا کولای شي هغوی ته د راتلونکې په هکله یو څه ووایي! لکه د یوې فاحشې ښځې په شان چې بې لارې کیږي، دوی خپل ځانونه نورو خدایانو ته سپارلي دي او زه یې پریښی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_12.mp3', '', 1761754199, 1761754199),
(39309, 'Hosea 4:13', 'Hosea', 4, 13, 'هغوی د غرونو په سرونو کې قربانۍ وړاندې کوي او په غونډیو، د څېړۍ ، سپېدار او چنار د ونو لاندې خوشبویئ سوځوي، ځکه چې ښایسته سیوری لري! نو له دې امله ستاسو لورګانې فاحشې شوې او ستاسو انږورګانې زنا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_13.mp3', '', 1761754199, 1761754199),
(39310, 'Hosea 4:14', 'Hosea', 4, 14, 'خو زه ستاسو لورګانو او انږورګانو ته د بدلمنتوب په خاطر سزا نه ورکوم. ځکه چې سړي د بتخانې فاحشو ته ورځي او د هغوی سره په زیارتونو کې قربانۍ وړاندې کوي. لکه چې یو متل دی: ‹کوم خلک چې عقل نه لري هغوی به تباه کیږي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea4_verse_14.mp3', '', 1761754199, 1761754199);